if(G._fireZones&&G._fireZones.length>0){
    // 겹침 캡 리셋: darkPillar/spikeTrap 장판이 실재할 때만 전 적 카운터 초기화 (O(적수) 매프레임 낭비 제거)
    let _hasCapZone=false;
    for(let _czi=0;_czi<G._fireZones.length;_czi++){const _ct=G._fireZones[_czi].type;if(_ct==='darkPillar'||_ct==='spikeTrap'){_hasCapZone=true;break}}
    if(_hasCapZone){for(let _ri=0;_ri<ens.length;_ri++){ens[_ri]._dpHitCap=0;ens[_ri]._stHitCap=0}}
    let _fzW=0;for(let _fzi=0;_fzi<G._fireZones.length;_fzi++){
      const fz=G._fireZones[_fzi];
      fz.t+=sp;
      // ═══ 부활의 영역 — 플레이어 버프 (부활력 체크는 사망 시) ═══
      if(fz.type==='weakRev'){
        if(fz.t>=fz.maxT){continue}
        if(Math.random()>.75){
          const _wa=Math.random()*Math.PI*2,_wd=Math.random()*fz.r;
          poolPart(fz.x+Math.cos(_wa)*_wd,fz.y+Math.sin(_wa)*_wd,
            (Math.random()-.5)*.5,-0.6-Math.random()*1,
            Math.random()>.5?'#ff4488':'#ff88aa',1+Math.random()*1.5,10+Math.random()*8);
        }
        G._fireZones[_fzW++]=fz;continue;
      }
      // ═══ 디버프 영역 (파쇄/침식/관통) — 적 디버프 적용 ═══
      if(fz.type==='weakPhys'||fz.type==='weakMag'||fz.type==='weakPj'){
        if(fz.t>=fz.maxT){continue}
        // 6프레임마다 범위 내 적에게 디버프 태그
        fz._wTick=(fz._wTick||0)+sp;
        if(fz._wTick>=6){fz._wTick=0;
          const _wNe=shQuery(fz.x,fz.y,fz.r);
          const _wPct=0.10+((fz.lv||1)-1)*0.01; // 10% + Lv당 1%
          for(let _wi=0;_wi<_wNe.length;_wi++){
            const e=_wNe[_wi];if(!e.alive)continue;
            if(dst(fz.x,fz.y,e.x,e.y)>fz.r)continue;
            if(fz.type==='weakPhys')e._weakPhys=Math.max(e._weakPhys||0,_wPct);
            else if(fz.type==='weakMag')e._weakMag=Math.max(e._weakMag||0,_wPct);
            else e._weakPj=Math.max(e._weakPj||0,_wPct);
            e._weakT=12; // 12프레임(0.2초) 후 자동 해제
          }
        }
        // 파티클
        if(Math.random()>.7){
          const _wa=Math.random()*Math.PI*2,_wd=Math.random()*fz.r;
          const _wCol=fz.type==='weakPhys'?'#ff6644':fz.type==='weakMag'?'#aa66ff':'#44aaff';
          poolPart(fz.x+Math.cos(_wa)*_wd,fz.y+Math.sin(_wa)*_wd,
            (Math.random()-.5)*.6,-0.5-Math.random()*1,
            _wCol,1+Math.random()*1.5,10+Math.random()*8);
        }
        G._fireZones[_fzW++]=fz;continue;
      }
      // ═══ 신의영역: 보호돔 (밖→안 차단) + 탄막 무효 ═══
      if(fz.type==='maliceDome'){
        if(fz.t>=fz.maxT){continue}
        // 적 강제 밀어내기 (보스 무시) — 좌표 즉시 경계 밖으로 + 속도 초기화
        const _mdNe=shQuery(fz.x,fz.y,fz.r+40);
        for(let _mi=0;_mi<_mdNe.length;_mi++){const e=_mdNe[_mi];if(!e.alive)continue;
          if(e.ib)continue;
          const _ed=dst(e.x,e.y,fz.x,fz.y);if(_ed>=fz.r)continue;
          const _ea=Math.atan2(e.y-fz.y,e.x-fz.x);
          e.x=fz.x+Math.cos(_ea)*(fz.r+8);e.y=fz.y+Math.sin(_ea)*(fz.r+8);
          e.vx=0;e.vy=0;e.kb.x=Math.cos(_ea)*6;e.kb.y=Math.sin(_ea)*6;
        }
        // 파티클 (금색)
        if(Math.random()>.7){const _mda=Math.random()*Math.PI*2;
          poolPart(fz.x+Math.cos(_mda)*fz.r,fz.y+Math.sin(_mda)*fz.r,(Math.random()-.5)*.5,-0.5-Math.random(),'#ffd700',1.5+Math.random()*2,10+Math.random()*8)}
        G._fireZones[_fzW++]=fz;continue}
      if(fz.type==='holyDome'||fz.type==='holyPrison'){
        if(fz.t>=fz.maxT){continue}else if(fz.type==='holyDome'&&Math.random()>.75){
          const _hda=Math.random()*Math.PI*2,_hdd=Math.random()*fz.r;
          poolPart(fz.x+Math.cos(_hda)*_hdd,fz.y+Math.sin(_hda)*_hdd,
            (Math.random()-.5)*.8,-0.8-Math.random()*1.2,
            '#b6ff54',1+Math.random()*2,12+Math.random()*10);
        }G._fireZones[_fzW++]=fz;continue} // 돔/감옥은 DOT 없음
      // ═══ 아이스스톰: 빙결 저항 -50% + 빙결 게이지 급속 축적 ═══
      if(fz.type==='iceStorm'){
        fz._iceTick=(fz._iceTick||0)+sp;
        if(fz._iceTick>=6){fz._iceTick=0;
          const _isNe=shQuery(fz.x,fz.y,fz.r);
          const _isLv=fz.lv||1;
          for(let _isi=0;_isi<_isNe.length;_isi++){
            const e=_isNe[_isi];if(!e.alive)continue;
            if(dst(fz.x,fz.y,e.x,e.y)>fz.r)continue;
            // 빙결 저항 디버프
            e._iceResDown=Math.max(e._iceResDown||0,30);
            // 빙결 게이지 강제 축적
            if((e._frozen||0)<=0&&(e._frozenImmune||0)<=0){
              if(!e._freezeMax)e._freezeMax=e.ib?500:100;
              if(!e._freezeGauge)e._freezeGauge=0;
              const _isAdd=e.ib?(15+_isLv*2):(35+_isLv*4);
              e._freezeGauge=Math.min(e._freezeMax,e._freezeGauge+_isAdd);
              if(e._freezeGauge>=e._freezeMax){
                e._frozen=180;e._freezeGauge=0;
                addTxt(e.x,e.y-25,_T('❄프리즌!'),'#44ddff',50);
                addParts(e.x,e.y,'#88eeff',12);void 0;
              }
            }
            // 감속
            e._webSlow=Math.max(e._webSlow||0,25);
            e.flashT=4;
          }
        }
        // 파티클 (간헐적 눈/얼음)
        if(Math.random()>.6){
          const _isa=Math.random()*Math.PI*2,_isd=Math.random()*fz.r;
          poolPart(fz.x+Math.cos(_isa)*_isd,fz.y+Math.sin(_isa)*_isd,
            (Math.random()-.5)*2,-1-Math.random()*2,
            Math.random()>.5?'#aaeeff':'#ffffff',1+Math.random()*2,8+Math.random()*6);
        }
        if(fz.t>=fz.maxT){continue};G._fireZones[_fzW++]=fz;continue;
      }
      // ═══ 폭풍소환 소용돌이: 적 흡인 + DOT ═══
      if(fz.type==='vortex'||fz.type==='iceVortex'){
        const _vtLv=fz.lv||1;
        const _vtPullBase=2.0+_vtLv*0.1; // lv1=2.1, lv20=4.0 (+0.1/lv)
        // 매 프레임 흡인 (중심에 가까울수록 강하게)
        const _vtNe=shQuery(fz.x,fz.y,fz.r+30);
        for(let _vi=0;_vi<_vtNe.length;_vi++){
          const e=_vtNe[_vi];if(!e.alive)continue;
          const d=dst(fz.x,fz.y,e.x,e.y);if(d>fz.r||d<5)continue;
          const ang=Math.atan2(fz.y-e.y,fz.x-e.x);
          const pullMul=(1-d/fz.r*0.6)*_vtPullBase*sp;
          e.x+=Math.cos(ang)*pullMul;e.y+=Math.sin(ang)*pullMul;
          e._webSlow=Math.max(e._webSlow||0,15);
        }
        // DOT 틱 (15프레임마다)
        if(~~(fz.t)%15<~~(sp)+1){
          for(let _vi=0;_vi<_vtNe.length;_vi++){
            const e=_vtNe[_vi];if(!e.alive)continue;
            if(dst(fz.x,fz.y,e.x,e.y)>fz.r)continue;
            if(fz.type==='iceVortex'){
              hurtE(e,~~(fz.dmg*.15),Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true},EL.I);
              e._webSlow=Math.max(e._webSlow||0,25);
              if((e._frozen||0)<=0&&(e._frozenImmune||0)<=0){
                if(!e._freezeMax)e._freezeMax=e.ib?500:100;
                if(!e._freezeGauge)e._freezeGauge=0;
                e._freezeGauge=Math.min(e._freezeMax,e._freezeGauge+(e.ib?10:25));
                if(e._freezeGauge>=e._freezeMax){e._frozen=180;e._freezeGauge=0;
                  addTxt(e.x,e.y-25,_T('❄프리즌!'),'#44ddff',50);addParts(e.x,e.y,'#88eeff',12);void 0}
              }
            }else{
              hurtE(e,~~(fz.dmg*.15),Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true},EL.D);
              e._webSlow=Math.max(e._webSlow||0,20);
            }
          }
        }
        // 소용돌이 파티클 (회전하며 중심으로 수렴)
        if(Math.random()>.4){
          const _vta=Math.random()*Math.PI*2,_vtd=Math.random()*fz.r;
          const _vtIce=fz.type==='iceVortex';
          const _vtCol=_vtIce?(Math.random()>.5?'#aaeeff':'#66ccff'):(Math.random()>.5?'#cc88ff':'#8844dd');
          const _tanAng=_vta+Math.PI/2;const _radAng=_vta+Math.PI;
          poolPart(fz.x+Math.cos(_vta)*_vtd,fz.y+Math.sin(_vta)*_vtd,
            Math.cos(_tanAng)*3+Math.cos(_radAng)*1.5,Math.sin(_tanAng)*3+Math.sin(_radAng)*1.5,
            _vtCol,1.5+Math.random()*2.5,10+Math.random()*8);
          // 상승 파티클
          if(Math.random()>.6){
            poolPart(fz.x+(Math.random()-.5)*fz.r*.6,fz.y+(Math.random()-.5)*fz.r*.6,
              (Math.random()-.5)*2,-2-Math.random()*3,
              _vtIce?'#ddf4ff':'#eeddff',1+Math.random()*1.5,5+Math.random()*5);
          }
        }
        if(fz.t>=fz.maxT){continue};G._fireZones[_fzW++]=fz;continue;
      }
      // ═══ 지옥진: 플레이어 추적 화염오라 + 화상 DOT ═══
      if(fz.type==='fireAura'){
        if(fz.follow){fz.x=P.x;fz.y=P.y}
        if(fz.t>=fz.maxT){continue}
        fz._tickCd=(fz._tickCd||0)+sp;
        if(fz._tickCd>=12){
          fz._tickCd=0;
          const _faNe=shQuery(fz.x,fz.y,fz.r+20);
          for(let _fi=0;_fi<_faNe.length;_fi++){
            const e=_faNe[_fi];if(!e.alive)continue;
            if(dst(fz.x,fz.y,e.x,e.y)>fz.r+e.r)continue;
            const ang=Math.atan2(e.y-fz.y,e.x-fz.x);
            hurtE(e,~~(fz.dmg*0.02),ang,true,{dot:true,shieldHit:true},EL.F); // 틱당 2%
            // 화상 부여 (5초)
            e.burn=1;e.burnT=Math.max(e.burnT||0,300);e.burnStk=Math.min(5,(e.burnStk||0)+1);
            if((e.burnStk||0)<10)e._burnPool=(e._burnPool||0)+pDotPool()*fz.dmg*0.01;
          }
        }
        if(Math.random()>.5){
          const _fpa=Math.random()*Math.PI*2,_fpd=Math.random()*fz.r;
          poolPart(fz.x+Math.cos(_fpa)*_fpd,fz.y+Math.sin(_fpa)*_fpd,
            (Math.random()-.5)*2,-1-Math.random()*2,
            Math.random()>.5?'#ff6600':'#ffaa00',2+Math.random()*2,8+Math.random()*6);
        }
        G._fireZones[_fzW++]=fz;continue;
      }
      // ═══ 참회: 8방향 마법진 회전 쐐기 데미지 ═══
      if(fz.type==='hellRay'){
        fz.ang=(fz.ang||0)+Math.PI*2/fz.maxT*sp; // 지속시간에 1회전
        // 8방향 팔 판정 — 45도 간격, 폭 40px
        if(~~(fz.t)%10<~~(sp)+1){
          const _hrNe=shQuery(fz.x,fz.y,fz.r+20);
          for(let _hi=0;_hi<_hrNe.length;_hi++){
            const e=_hrNe[_hi];if(!e.alive||e._hrHitT===~~(fz.t))continue;
            const _dx=e.x-fz.x,_dy=e.y-fz.y;
            const _ed=Math.sqrt(_dx*_dx+_dy*_dy);
            if(_ed>fz.r+e.r)continue;
            // 8팔 중 하나와 정렬되면 히트
            let _hrHit=false;
            for(let _ai=0;_ai<4;_ai++){
              const _a=fz.ang+_ai*Math.PI*.25;
              const _c=Math.cos(_a),_s=Math.sin(_a);
              const _perp=Math.abs(-_dx*_s+_dy*_c);
              if(_perp<=40+e.r){_hrHit=true;break}
            }
            if(!_hrHit)continue;
            e._hrHitT=~~(fz.t);
            hurtE(e,fz.dmg,0,true,{shieldHit:true,noKB:true},fz.el);
          }
        }
        // 쐐기 팔 파티클
        if(Math.random()>.5){
          const _ai=~~(Math.random()*2);const _a=fz.ang+_ai*Math.PI*.5;
          const _hrd=(Math.random()*2-1)*fz.r;
          poolPart(fz.x+Math.cos(_a)*_hrd,fz.y+Math.sin(_a)*_hrd,
            (Math.random()-.5)*2,-1-Math.random()*2,
            Math.random()>.5?'#ffd700':'#fff8dc',1.5+Math.random()*2,8+Math.random()*6);
        }
        if(fz.t>=fz.maxT){continue};G._fireZones[_fzW++]=fz;continue;
      }
      // DOT 틱 — 타이머 기반 (fps 무관, 정확한 간격)
      const _fzTick=fz.type==='dim'?60:fz.type==='dimPoison'?20:fz.type==='dimLightning'?20:fz.type==='shockField'?20:fz.type==='spikeTrap'?25:(fz.type==='storm'||fz.type==='boneStorm')?18:fz.type==='darkPillar'?30:fz.type==='assaultFlame'?20:fz.type==='fireTrail'?15:30;
      if(!fz._tickTimer)fz._tickTimer=0;
      fz._tickTimer+=sp;
      if(fz._tickTimer>=_fzTick){fz._tickTimer-=_fzTick;
        // 동일 타입 존 겹침 캡: darkPillar/spikeTrap은 적당 최대 2존까지만 히트
        const _fzCapType=fz.type==='darkPillar'||fz.type==='spikeTrap';
        const _fzNe=shQuery(fz.x,fz.y,fz.r); // 깊이 버퍼 — .slice() 제거
        _shBufI++;
        for(let _fei=0;_fei<_fzNe.length;_fei++){
          const e=_fzNe[_fei];if(!e.alive)continue;
          const _fed=dst(fz.x,fz.y,e.x,e.y);if(_fed>fz.r)continue;
          // 겹침 캡 체크: 이번 틱에 이 적이 같은 타입 존에서 이미 2회 피격됐으면 스킵
          if(_fzCapType){
            const _capKey=fz.type==='darkPillar'?'_dpHitCap':'_stHitCap';
            if(!e[_capKey])e[_capKey]=0;
            if(e[_capKey]>=1)continue;
            e[_capKey]++;
          }
          if(fz.type==='dim'){
            const _dimDot=~~(e.mhp*(fz.hpPct||0.05));
            e.hp-=Math.max(1,_dimDot);
            e.bleedT=Math.max(e.bleedT||0,300);e.bleedStk=Math.min(10,(e.bleedStk||0)+1);if((e.bleedStk||0)<10)e._bleedPool=(e._bleedPool||0)+pDotPool()*_dimDot*0.10;
            e.poisonT=Math.max(e.poisonT||0,300);e.poisonStk=Math.min(10,(e.poisonStk||0)+1);if((e.poisonStk||0)<10)e._poisonPool=(e._poisonPool||0)+pDotPool()*_dimDot*0.10;
            e.bleed=1;e.poison=1;
            e.flashT=6;
            if(e.hp<=0){e.hp=0;atkTicketRelease(e);e.alive=false;G.kills++;G._stageKills=(G._stageKills||0)+1;_regKill(e);e.deathAng=Math.atan2(e.y-fz.y,e.x-fz.x);deathFX(e.x,e.y,e.r,e.col,!!e.ib,false,e.etype);_addCorpse(e,e.deathAng,2)}
          }else if(fz.type==='dimPoison'){
            hurtE(e,fz.dmg,Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true},EL.D);
            e.poisonT=Math.max(e.poisonT||0,300);e.poisonStk=Math.min(10,(e.poisonStk||0)+1);if((e.poisonStk||0)<10)e._poisonPool=(e._poisonPool||0)+pDotPool()*fz.dmg*0.10;e.poison=1;
            e._webSlow=Math.max(e._webSlow||0,15);
          }else if(fz.type==='storm'){
            // 악의폭풍: 번개 마법 DOT + 감속 (쉴드 적용)
            hurtE(e,fz.dmg,Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true},fz.el||EL.L);
            e._webSlow=Math.max(e._webSlow||0,20);
          }else if(fz.type==='darkPillar'){
            // 악의기둥: 암흑 마법 DOT + 감속 (쉴드 적용)
            hurtE(e,fz.dmg,Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true},EL.D);
            e._webSlow=Math.max(e._webSlow||0,25);
          }else if(fz.type==='boneStorm'){
            // 해골번개: 암흑 마법 DOT + 감속 (쉴드 적용)
            hurtE(e,fz.dmg,Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true},EL.D);
            e._webSlow=Math.max(e._webSlow||0,25);
          }else if(fz.type==='dimLightning'){
            // 사슬이동:강화 번개길: 번개 마법 DOT + 감전 (쉴드 적용)
            hurtE(e,fz.dmg,Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true},EL.L);
            e.shockT=Math.max(e.shockT||0,60);
          }else if(fz.type==='shockField'){
            // 전격이동 전류장판: 번개 틱뎀 + 전류 방어력 감소 (마법기반 — 에너지쉴드 적용)
            hurtE(e,fz.dmg,Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true},EL.L);
            e._shockDR=Math.max(e._shockDR||0,fz.defRed||.10); // 방어력 감소 디버프
            e._shockDRT=60; // 장판 밖으로 나가도 1초 유지
          }else if(fz.type==='spikeTrap'){
            // 가시덫: 물리 DOT + 슬로우(기본 91%, Lv당+2%p, 최대95%) + 출혈
            if(Math.random()<.3)playSampleAt('melee_hit1',.25,_r(1.2,.15),e.x,e.y);
            hurtE(e,fz.dmg,Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true,_lessonAttack:'spikeTrap'},EL.P);
            e.bleedT=Math.max(e.bleedT||0,300);e.bleedStk=Math.min(10,(e.bleedStk||0)+1);if((e.bleedStk||0)<10)e._bleedPool=(e._bleedPool||0)+pDotPool()*fz.dmg*0.10;e.bleed=1;
            if(!e._spikeSlow||e._spikeSlow<=0)addTxt(e.x,e.y-15,'🌿'+~~(_spikeTrapSlowPct(fz.lv)*100)+'%','#66aa44',25);
            e._spikeSlow=Math.max(e._spikeSlow||0,90); // 1.5초 갱신
            e._spikeSlowLv=fz.lv||1;
          }else if(fz.type==='assaultFlame'){
            // 기동칼날개 불바닥: 화염 마법 DOT + 화상 (쉴드 적용)
            hurtE(e,fz.dmg,Math.atan2(e.y-fz.y,e.x-fz.x),true,{dot:true,shieldHit:true},EL.F);
            e.burnT=180;e.burnStk=Math.min(10,(e.burnStk||0)+1);if((e.burnStk||0)<10)e._burnPool=(e._burnPool||0)+pDotPool()*fz.dmg*0.10;
          }else if(fz.type==='fireTrail'){
